const symbol = $('Iterate Stocks').first().json.symbol;
const quantity = $('Iterate Stocks').first().json.quantity;
const avg_price = $('Iterate Stocks').first().json.avg_price;
const current_price = $('Iterate Stocks').first().json.current_price;
const invested = $('Iterate Stocks').first().json.invested;
const value = $('Iterate Stocks').first().json.value;
const pnl = $('Iterate Stocks').first().json.pnl;
const return_pct = $('Iterate Stocks').first().json.return_pct;

const portfolio = {
  quantity,
  avg_price,
  current_price,
  invested,
  value,
  pnl,
  return_pct
}

let news = [];

items.forEach(element=>{
  news.push(
    {
      title: element.json.title,
      link: element.json.link
    }
  );
});

return [{
  json: {
    symbol,
    portfolio,
    news
  }
}];

const rawOutputs = $json.output;

// Convert string → JSON
const parsed = rawOutputs.map(str => JSON.parse(str));

return [{
  json: {
    stocks: parsed
  }
}];

const aiRaw = $json.output;

// Remove markdown formatting
const clean = aiRaw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const ai = JSON.parse(clean);

return [{
  json: {
    portfolio_ai: ai
  }
}];

const items = $input.all();

// Extract portfolio AI (first item)
const ai = items[0].json.portfolio_ai || {};

// Extract stocks (second item)
const stocks = items[1].json.stocks || [];

let report = `Portfolio Report\n\n`;

// Portfolio Section
report += `Portfolio Insights\n`;
report += `• View: ${ai.portfolio_view || 'N/A'}\n`;
report += `• Drivers: ${ai.drivers || 'N/A'}\n`;
report += `• Risks: ${ai.risks || 'N/A'}\n`;
report += `• Strategy: ${ai.strategy || 'N/A'}\n\n`;

// Stock Section
report += `Stock-wise Analysis\n`;

stocks.forEach(s => {

  report += `\n${s.symbol}\n`;
  report += `Sentiment: ${s.sentiment || 'N/A'}\n`;
  report += `${s.insight || 'No insight available'}\n`;
});

return [{
  json: {
    report_text: report
  }
}];
